using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;

namespace TokenGrove {
  static class SelfTests {
    static int count;
    static void Check(bool success,string label){if(!success)throw new Exception("FAIL: "+label);Console.WriteLine("PASS: "+label);count++;}
    static byte[] Hex(string s){return Enumerable.Range(0,s.Length/2).Select(i=>Convert.ToByte(s.Substring(i*2,2),16)).ToArray();}
    public static void Run(){
      var root=Path.GetFullPath(Environment.GetEnvironmentVariable("TOKEN_GROVE_TEST_ROOT")??Path.GetTempPath());var dir=Path.Combine(root,"token-grove-native-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
      try{
        var zero16=new byte[16];Check(LocalCrypto.DecryptGcm(zero16,new byte[12],Hex("0388dace60b6a392f328c2b971b2fe78"),Hex("ab6e47d42cec13bdf53a67b21257bddf")).SequenceEqual(zero16),"AES-GCM NIST 128-bit authenticated vector");
        Check(LocalCrypto.DecryptGcm(new byte[32],new byte[12],Hex("cea7403d4d606b6e074ec5d3baf39d18"),Hex("d0d1c8a799996bf0265b98b5d48ab919")).SequenceEqual(zero16),"AES-GCM NIST 256-bit authenticated vector");
        bool rejected=false;try{LocalCrypto.DecryptGcm(zero16,new byte[12],Hex("0388dace60b6a392f328c2b971b2fe78"),new byte[16]);}catch(CryptographicException){rejected=true;}Check(rejected,"Tampered encrypted payload is rejected");
        var now=DateTime.UtcNow;var ms=(now-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalMilliseconds;
        J.Write(Path.Combine(dir,"plan-usage-history.json"),new{version=2,samples=new[]{new{t=ms,org="fixture",u=new{fh=0,sd=93}}}});
        var desktop=DataCollector.ReadHistory(dir,true);Check(desktop.Available&&desktop.windows.Count==2&&desktop.source.Contains("Desktop"),"Running Desktop is detected independently of CLI authentication");Check(desktop.Five.usedPercent==0&&desktop.Week.usedPercent==93&&desktop.Five.resetsAt==null,"Desktop zero usage is known; missing reset stays unknown");
        var nativeWindows=DataCollector.CodexWindows(J.Parse("{\"primary\":{\"usedPercent\":null,\"windowDurationMins\":60},\"secondary\":{\"usedPercent\":25,\"windowDurationMins\":10080}}"),J.Iso(now));Check(nativeWindows[0].usedPercent==null&&nativeWindows[0].label=="1 小时额度"&&nativeWindows[1].label=="每周额度","Codex preserves actual duration and unknown values");
        var cursor=new DataCollector.FileCursor{session="fixture",model="model-a"};Func<int,object> e=total=>J.Parse("{\"type\":\"event_msg\",\"timestamp\":\""+J.Iso(now)+"\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":"+(total-10)+",\"cached_input_tokens\":80,\"output_tokens\":10,\"total_tokens\":"+total+"}}}}");
        var first=DataCollector.CodexRecord(e(110),cursor);var same=DataCollector.CodexRecord(e(110),cursor);var second=DataCollector.CodexRecord(e(210),cursor);Check(first.total==110&&same==null&&second.total==100,"Codex cumulative updates only count new tokens");
        Func<int,string> assistant=output=>"{\"type\":\"assistant\",\"timestamp\":\""+J.Iso(now)+"\",\"sessionId\":\"fixture\",\"message\":{\"id\":\"m\",\"model\":\"sonnet\",\"usage\":{\"input_tokens\":100,\"output_tokens\":"+output+",\"cache_read_input_tokens\":200,\"cache_creation_input_tokens\":50}}}";
        var cr=DataCollector.ClaudeRecord(J.Parse(assistant(30)));Check(cr.total==380&&cr.cached==200&&cr.write==50,"Claude cache reads and writes are independently counted");
        var file=Path.Combine(dir,"active.jsonl");File.WriteAllText(file,assistant(10)+"\n"+assistant(30).Substring(0,35));var collector=new DataCollector();var r1=collector.ReadUsageFile(file,"claude");File.AppendAllText(file,assistant(30).Substring(35)+"\n");var r2=collector.ReadUsageFile(file,"claude");Check(r1.Count==1&&r1[0].total==360&&r2.Count==1&&r2[0].total==380,"Incremental reader preserves partial lines and deduplicates streaming updates");
        var a=new Account{provider="claude",windows=new List<WindowQuota>{new WindowQuota{id="five_hour",usedPercent=50,windowMinutes=300,resetsAt=J.Iso(now.AddHours(2)),observedAt=J.Iso(now)}}};var records=new List<Record>{new Record{provider="claude",total=20000,time=now.AddMinutes(-1)}};Check(DataCollector.Calculate(a,records)?.remainingTokens==20000,"Estimate only uses matching quota-window samples");a.Five.usedPercent=0;Check(DataCollector.Calculate(a,records)==null,"Zero-percent usage never fabricates a token balance");
        var invalid=new Snapshot{updatedAt=J.Iso(now),accounts=new List<Account>{new Account{id="x",provider="claude",windows=new List<WindowQuota>{new WindowQuota{usedPercent=101}}}}};var bad=Path.Combine(dir,"invalid.json");J.Write(bad,invalid);rejected=false;try{ImportExport.LoadSnapshot(bad);}catch(InvalidDataException){rejected=true;}Check(rejected,"Snapshot import rejects out-of-range percentages");
        var legacy=Path.Combine(dir,"legacy.json");File.WriteAllText(legacy,"{\"version\":1,\"accounts\":[{\"id\":\"legacy\",\"provider\":\"claude\",\"windows\":[],\"estimate\":{\"remainingTokens\":244000,\"sampleTokens\":398105.2631578947,\"sampleUsedPercent\":62}}],\"models\":[],\"daily\":[]}");Check(ImportExport.LoadSnapshot(legacy).accounts[0].estimate.sampleTokens==398105,"Legacy browser snapshots with fractional estimate samples import correctly");
        var originalRoot=Settings.Root;Settings.Root=Path.Combine(dir,"preferences");
        try{
          J.Write(Path.Combine(Settings.Root,"settings.json"),new{dark=false,topmost=false,privacy=true,intervalSeconds=600});var prefs=Settings.Load();
          Check(prefs.themeMode=="system"&&prefs.widgetOpacity==96&&prefs.mainOpacity==100&&!prefs.topmost&&prefs.privacy&&prefs.intervalSeconds==600,"Older preferences gain system theme and opacity defaults without losing existing choices");
          Check(prefs.EffectiveDark(true)&&!prefs.EffectiveDark(false),"System theme resolves both light and dark appearances");
          prefs.themeMode="light";bool light=!prefs.EffectiveDark(true);prefs.themeMode="dark";Check(light&&prefs.EffectiveDark(false),"Manual theme overrides remain independent of Windows theme");
          prefs.themeMode="invalid";prefs.widgetOpacity=-20;prefs.mainOpacity=200;prefs.Normalize();Check(prefs.themeMode=="system"&&prefs.widgetOpacity==55&&prefs.mainOpacity==100,"Invalid appearance values normalize to readable opacity limits");
          prefs.themeMode="dark";prefs.widgetOpacity=81;prefs.mainOpacity=86;prefs.Save();var restored=Settings.Load();Check(restored.themeMode=="dark"&&restored.widgetOpacity==81&&restored.mainOpacity==86,"Theme and independent opacity settings persist across reloads");
        }finally{Settings.Root=originalRoot;}
        var historic=Path.Combine(dir,"historic.jsonl");File.WriteAllText(historic,assistant(30).Replace(J.Iso(now),J.Iso(now.AddDays(-80)))+"\n");Check(new DataCollector().ReadUsageFile(historic,"claude").Count==1,"Historical queries retain records older than the 30-day dashboard");
        var from=new DateTime(2026,1,10,10,0,0,DateTimeKind.Utc);var to=from.AddHours(2);var rangeRows=new List<Record>{new Record{provider="claude",model="opus",time=from.AddTicks(-1),total=100},new Record{provider="claude",model="opus",time=from,total=200},new Record{provider="chatgpt",model="gpt-model",time=from.AddHours(1),total=300},new Record{provider="claude",model="opus",time=to,total=400}};
        Check(UsageEngine.Query(rangeRows,from,to).totals.total==500&&UsageEngine.Query(rangeRows,from,to).records==2,"Time queries include the start and exclude the exact end without leaking adjacent activity");
        Check(UsageEngine.Query(rangeRows,from,to,"chatgpt","GPT").totals.total==300&&UsageEngine.Query(rangeRows,from,to,"claude","gpt").records==0,"Provider and model filters apply together, ignoring model-name case");
        var cacheRows=new[]{cr,new Record{provider="chatgpt",model="gpt",time=now,input=120,output=30,cached=100,total=150}};Check(UsageEngine.Query(cacheRows,now.AddMinutes(-1),now.AddMinutes(1)).totals.total==530,"Range totals preserve Claude cache accounting without adding Codex cache twice");
        var quotaRows=new[]{new Record{provider="claude",time=now.AddHours(-4),total=100},new Record{provider="claude",time=now.AddHours(-2),total=200},new Record{provider="claude",time=now.AddDays(-2),total=400},new Record{provider="chatgpt",time=now.AddHours(-1),total=800}};
        var fiveTokens=UsageEngine.ForWindow("claude",new WindowQuota{windowMinutes=300,resetsAt=J.Iso(now.AddHours(2))},quotaRows,now);var weekTokens=UsageEngine.ForWindow("claude",new WindowQuota{windowMinutes=10080,resetsAt=J.Iso(now.AddDays(6))},quotaRows,now);Check(fiveTokens.usedTokens==200&&weekTokens.usedTokens==300,"Five-hour and weekly Token counts anchor to official reset times rather than rolling lookbacks");
        Check(UsageEngine.ForWindow("claude",new WindowQuota{usedPercent=0,windowMinutes=300},quotaRows,now).usedTokens==null&&UsageEngine.ForWindow("claude",new WindowQuota{windowMinutes=300,resetsAt=J.Iso(now.AddSeconds(-1))},quotaRows,now).state=="expired","Unknown and expired quota windows never fabricate a Token count");
        Check(UsageEngine.ForWindow("claude",new WindowQuota{windowMinutes=300,resetsAt=J.Iso(now.AddHours(5))},quotaRows,now).usedTokens==0,"A newly started known quota window safely reports zero local Tokens");
        rejected=false;try{UsageEngine.Query(rangeRows,to,from);}catch(ArgumentException){rejected=true;}Check(rejected,"Reversed date ranges are rejected instead of silently displaying zero");
        var midnight=DateTime.Today;var midnightRows=new[]{new Record{provider="claude",time=midnight.AddSeconds(-1).ToUniversalTime(),total=10},new Record{provider="chatgpt",time=midnight.ToUniversalTime(),total=20}};var midnightResult=UsageEngine.Query(midnightRows,midnight.AddHours(-1),midnight.AddHours(1));Check(midnightResult.totals.total==30&&midnightResult.daily.Count==2&&midnightResult.daily[1].date==midnight.ToString("yyyy-MM-dd"),"Local-date reports split correctly at midnight after UTC conversion");
        var quotaSnapshot=new Snapshot{accounts=new List<Account>{new Account{id="quota",provider="claude",windows=new List<WindowQuota>{new WindowQuota{id="five_hour",windowMinutes=300,resetsAt=J.Iso(now.AddHours(2)),localUsage=fiveTokens}}}}};var quotaFile=Path.Combine(dir,"quota-tokens.json");J.Write(quotaFile,quotaSnapshot);Check(ImportExport.LoadSnapshot(quotaFile).accounts[0].Five.localUsage.usedTokens==200,"Window Token counts and measurement times survive snapshot export/import");
        quotaSnapshot.accounts[0].Five.localUsage.usedTokens=-1;J.Write(quotaFile,quotaSnapshot);rejected=false;try{ImportExport.LoadSnapshot(quotaFile);}catch(InvalidDataException){rejected=true;}Check(rejected,"Snapshot import rejects invalid window Token metadata");
        Check(Typography.BundledFontLoaded&&(Typography.FamilyName.Contains("小站")||Typography.FamilyName.Contains("Token Grove")),"Bundled rounded typeface loads privately without installing a system font");
        using(var bitmap=new System.Drawing.Bitmap(320,42))using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.Clear(System.Drawing.Color.FromArgb(24,24,24));Art.Text(graphics,"圆润字体 5 小时 109.02M",3,3,13,System.Drawing.Color.FromArgb(240,240,240));int gray=0,colored=0;for(int y=0;y<bitmap.Height;y++)for(int x=0;x<bitmap.Width;x++){var pixel=bitmap.GetPixel(x,y);if(pixel.R!=pixel.G||pixel.G!=pixel.B)colored++;if(pixel.R==pixel.G&&pixel.G==pixel.B&&pixel.R>24&&pixel.R<240)gray++;}Check(gray>50&&colored==0,"Text on standalone panels uses smooth grayscale edges without inheriting ClearType or aliased defaults");}
        var trend=UsageEngine.Query(rangeRows,from,to);Check(trend.trend.Sum(b=>b.claude+b.chatgpt)==trend.totals.total&&trend.trend.Sum(b=>b.records)==trend.records,"Trend buckets preserve exact range totals and record counts");
        var cachedQuery=UsageEngine.Query(new[]{cr,first},now.AddMinutes(-1),now.AddMinutes(1));Check(cachedQuery.totals.freshInput==120&&cachedQuery.totals.cached==280,"Fresh input excludes Codex cache while retaining Claude independent cache accounting");
        var many=Enumerable.Range(0,127).Select(i=>new Record{provider=i%2==0?"claude":"chatgpt",model="test",time=from.AddSeconds(i),total=i+1}).ToArray();var p1=UsageEngine.Page(many,from,from.AddMinutes(3),null,null,0,50);var p2=UsageEngine.Page(many,from,from.AddMinutes(3),null,null,50,50);Check(p1.Count==50&&p2.Count==50&&p1[0].total==127&&p2[0].total==77&&!p1.Intersect(p2).Any(),"Record pages are newest first, bounded to 50 rows, and do not overlap");
        var filteredPage=UsageEngine.Page(many,from.AddSeconds(10),from.AddSeconds(20),"claude","TEST",0,50);Check(filteredPage.Count==5&&filteredPage[0].total==19&&filteredPage.Last().total==11,"Paged records share provider, model and start-inclusive/end-exclusive range filters");
        var wide=UsageEngine.Query(many,from.AddYears(-2),from.AddYears(2));Check(wide.trend.Count<=61&&wide.totals.total==many.Sum(r=>r.total),"Long-range trend stays bounded while retaining every token");
        var fiveWindow=new WindowQuota{id="five_hour",usedPercent=50,windowMinutes=300,resetsAt=J.Iso(now.AddHours(2)),observedAt=J.Iso(now)};var weekWindow=new WindowQuota{id="seven_day",usedPercent=25,windowMinutes=10080,resetsAt=J.Iso(now.AddDays(4)),observedAt=J.Iso(now)};
        var estimateRows=new[]{new Record{provider="claude",time=now.AddDays(-2),total=4000},new Record{provider="claude",time=now.AddHours(-2),total=2000},new Record{provider="chatgpt",time=now.AddHours(-1),total=8000}};
        var fiveEstimate=DataCollector.CalculateWindow("claude",fiveWindow,estimateRows,now);var weeklyEstimate=DataCollector.CalculateWindow("claude",weekWindow,estimateRows,now);Check(fiveEstimate.remainingTokens==2000&&weeklyEstimate.remainingTokens==18000&&weeklyEstimate.sampleTokens==6000&&weeklyEstimate.windowId=="seven_day","Five-hour and weekly estimates use their own provider-matched quota samples");
        weekWindow.observedAt=J.Iso(now.AddMinutes(-31));Check(DataCollector.CalculateWindow("claude",weekWindow,estimateRows,now)==null,"Weekly estimates reject stale official percentages");weekWindow.observedAt=J.Iso(now);weekWindow.usedPercent=0;Check(DataCollector.CalculateWindow("claude",weekWindow,estimateRows,now)==null,"Weekly zero usage does not fabricate a token capacity");weekWindow.usedPercent=25;weekWindow.resetsAt=null;Check(DataCollector.CalculateWindow("claude",weekWindow,estimateRows,now)==null,"Weekly estimates require a known quota window");weekWindow.resetsAt=J.Iso(now.AddDays(4));weekWindow.estimate=weeklyEstimate;
        var estimateSnapshot=new Snapshot{accounts=new List<Account>{new Account{id="estimates",provider="claude",estimate=fiveEstimate,weekEstimate=weeklyEstimate,windows=new List<WindowQuota>{fiveWindow,weekWindow}}}};var estimateFile=Path.Combine(dir,"estimates.json");J.Write(estimateFile,estimateSnapshot);var estimateReload=ImportExport.LoadSnapshot(estimateFile);Check(estimateReload.accounts[0].Week.estimate.remainingTokens==18000&&estimateReload.accounts[0].weekEstimate.windowId=="seven_day","Weekly estimate and its window metadata survive snapshot import and export");
        weekWindow.resetsAt=J.Iso(now.AddDays(5));Check(!weeklyEstimate.Current(weekWindow,now),"A changed reset time invalidates the previous window estimate");weekWindow.estimate.remainingTokens=-1;J.Write(estimateFile,estimateSnapshot);rejected=false;try{ImportExport.LoadSnapshot(estimateFile);}catch(InvalidDataException){rejected=true;}Check(rejected,"Snapshot import rejects invalid nested weekly estimates");
        CodexUsageRegressionTests.Run(dir,Check);PlanRegressionTests.Run(dir,Check);UiRegressionTests.Run(dir,Check);
        Console.WriteLine("All "+count+" native regression checks passed.");
      }finally{var checkedPath=Path.GetFullPath(dir);if(checkedPath.StartsWith(root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(checkedPath).StartsWith("token-grove-native-tests-"))Directory.Delete(checkedPath,true);}
    }
  }
}
